"use strict";

// The table's functions take their callback last. These wrappers accept
// whatever arguments the caller passes and append the callback themselves,
// so each one returns a function of any number of arguments.
function asSync(task) {
  return (...given) => {
    const outcome = { failed: false, error: undefined, value: undefined };
    given.push((error, value) => {
      outcome.failed = Boolean(error);
      outcome.error = error;
      outcome.value = value;
    });
    task(...given);
    if (outcome.failed) throw outcome.error;
    return outcome.value;
  };
}

function asPromise(task) {
  return (...given) =>
    new Promise((resolve, reject) => {
      given.push((error, value) => (error ? reject(error) : resolve(value)));
      task(...given);
    });
}

module.exports = { asSync, asPromise };
